const cds = require('@sap/cds');

module.exports = cds.service.impl(async function () {
    const { Project, Member, SFSF_User } = this.entities;

    this.on('READ', Project, async (req) => {
        const projects = await SELECT.from(Project);
        return projects;
    });

    this.before('CREATE', Member, async (req) => {
        req.data.createdAt = new Date();
    });

    this.after('READ', SFSF_User, (results) => {
        return results.map(r => ({ ...r, fetched: true }));
    });
});

